/* айқын полюсті генератордың диаграммасы (Кацман белгілеулері) */
function figBlondel(lead) {
  const psi = lead ? -40 : 50, s = Math.sin(rad(psi)), c = Math.cos(rad(psi)), E0 = lead ? 120 : 150, a = 60, bq = 62, xs = 22, ra = 14, IL = 70;
  const d = D(lead ? 130 : 100, lead ? 208 : 200);
  const I = [s * IL, c * IL], T0 = [0, E0];
  const Ead = [0, -s * a], Eaq = [c * bq, 0], Es = [c * xs, -s * xs], Er = [-s * ra, -c * ra];
  const add = (p, q) => [p[0] + q[0], p[1] + q[1]];
  const chain = lead ? [Ead, Eaq, Es, Er] : [Eaq, Ead, Es, Er];
  let p = T0, b = d.v('v1', [0, 0], T0), P = [T0];
  chain.forEach(v => { const q = add(p, v); b += d.v('v3', p, q); P.push(q); p = q; });
  const U = p, aU = Math.atan2(U[1], U[0]) * 180 / Math.PI, aI = 90 - psi;
  b += d.v('v4', [0, 0], U) + d.v('ds', I, [I[0], 0]) + d.v('ds', I, [0, I[1]]) + d.v('v2', [0, 0], [I[0], 0]) + d.v('v2', [0, 0], [0, I[1]]) + d.v('v2', [0, 0], I);
  b += d.arc(22, 90, aI) + d.arc(lead ? 60 : 70, 90, aU) + d.arc(lead ? 40 : 52, aU, aI);
  if (!lead) {
    b += d.t(-8, 105, 'Ė₀', 'end f1') + d.t(20, 156, sub('Ė', 'aq'), 'mid sm f3') + d.t(46, 122, sub('Ė', 'ad'), 'sm f3') + d.t(56, 90, '−jX<tspan dy="3" font-size="9">σ</tspan><tspan dy="-3">İ</tspan>', 'sm f3') + d.t(54, 70, '−R<tspan dy="3" font-size="9">a</tspan><tspan dy="-3">İ</tspan>', 'sm f3')
      + d.t(21, 50, 'U̇', 'end f4') + d.t(58, 42, 'İ', 'f2') + d.t(30, -14, sub('İ', 'd'), 'mid sm f2') + d.t(-6, 22, sub('İ', 'q'), 'end sm f2')
      + d.at(31, 76, 'ψ') + d.at(80, 77, 'θ') + d.at(44, 50, 'φ');
  } else {
    b += d.t(-8, 95, 'Ė₀', 'end f1') + d.t(-6, 136, sub('Ė', 'ad'), 'end sm f3') + d.t(22, 146, sub('Ė', 'aq'), 'mid sm f3') + d.t(52, 180, '−jX<tspan dy="3" font-size="9">σ</tspan><tspan dy="-3">İ</tspan>', 'end sm f3') + d.t(80, 166, '−R<tspan dy="3" font-size="9">a</tspan><tspan dy="-3">İ</tspan>', 'sm f3')
      + d.t(46, 78, 'U̇', 'f4') + d.t(-49, 58, 'İ', 'end f2') + d.t(-24, -14, sub('İ', 'd'), 'mid sm f2') + d.t(-6, 68, sub('İ', 'q'), 'end sm f2')
      + d.at(33, 110, 'ψ') + d.at(70, 79, 'θ') + d.at(52, 56, 'φ');
  }
  return svg(lead ? 270 : 240, lead ? 232 : 228, b);
}
