    o: [['A сызығы – cosφ = 1 нүктелері (статор тогы ең аз)', 1], ['б аймағы – асқын қоздыру: генератор желіге реактивті қуат береді', 1], ['3-қисық ең үлкен активті қуатқа сәйкес', 1], ['A сызығы – орнықтылық шегі', 0], ['B сызығы – cosφ = 1 нүктелері', 0], ['а аймағы – асқын қоздыру', 0], ['1-қисық ең үлкен активті қуатқа сәйкес', 0], ['A сызығының оң жағында генератор желіден реактивті қуат тұтынады', 0]],
